namespace BODA.VMS.MLOps.Tests.TestAssets;

/// <summary>
/// 스텁 ONNX — VMS 리포 VMS.Core.Tests/DetectionModelFormatProbeTests.cs 와 동일 자산 (8 쿼리·2 클래스 상수 그래프).
/// 규약 계약 테스트(개발 문서 §11)용. 세션 생성 없이 protobuf 만 읽는다.
/// </summary>
public static class OnnxStubs
{
    /// <summary>D-FINE deploy 규약 + metadata_props(names/imgsz/model_format=dfine)</summary>
    public const string DeployWithMeta =
        "";

    /// <summary>D-FINE deploy 규약, 메타데이터 없음 (그래프 입출력 이름으로만 판별)</summary>
    public const string DeployNoMeta =
        "";

    /// <summary>HF 원본 규약 (pixel_values → logits/pred_boxes), names 메타만</summary>
    public const string RawHf =
        "";

    /// <summary>Ultralytics YOLO 규약: images[1,3,640,640] → output0[1,6,8], names 메타</summary>
    public const string YoloStub =
        "";

    public static byte[] Bytes(string base64) => Convert.FromBase64String(base64);

    public sealed class TempOnnx : IDisposable
    {
        public string Path { get; }
        public TempOnnx(string base64, string tag = "stub")
        {
            Path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"mlops-{tag}-{Guid.NewGuid():N}.onnx");
            File.WriteAllBytes(Path, Bytes(base64));
        }
        public void Dispose() { try { File.Delete(Path); } catch { } }
    }
}
